pub fn dispatch_entity_withdrawal_dispute(
    repo: &mut impl crate::kernel::Repository<ATMCard>,
    parent_id: &str,
    element_id: &str,
    element_wants: &str,
    args: WithdrawalDisputeEntityArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<ATMCard> {
    args.narrative.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, ATMCARD_PROJECTED_FIELDS);

    crate::kernel::dispatch_entity(
        repo,
        parent_id,
        |r: &ATMCard| &r.withdrawals,
        |r: &mut ATMCard| &mut r.withdrawals,
        |el: &Withdrawal| el.identity() == element_id,
        "Dispute",
        "Banking::ATMCard",
        "ATMCard",
        "serial.value",
        "Withdrawal",
        "sequence.value",
        element_wants,
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "customer is active",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("parent.account_customer_status")),
                    right: Box::new(Expr::Str("active".to_string())),
                },
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "account is open",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("parent.account_status")),
                    right: Box::new(Expr::Str("open".to_string())),
                },
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "card is not retired",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: true,
                    },
                    left: Box::new(Expr::Lookup("parent.status")),
                    right: Box::new(Expr::Str("retired".to_string())),
                },
                corrects_event: None,
            },
        ],
        Some(crate::kernel::TransitionCheck {
            field: "state",
            from_states: &["taken"],
        }),
        |record| {
            record.narrative = args.narrative.clone();
            record.state = "disputed".to_string();
            Ok(())
        },
        &[],
        &atmcard_invariants(),
        &["WithdrawalDisputed"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

