impl crate::kernel::SetProjectedField for ATMCard {
    fn set_projected_field(&mut self, name: &'static str, value: Option<crate::kernel::Value>) {
        match name {
            "account_status" => {
                self.account_status = value.and_then(crate::kernel::Value::into_string)
            }
            "account_customer_status" => {
                self.account_customer_status = value.and_then(crate::kernel::Value::into_string)
            }
            _ => {}
        }
    }
}

pub static ATMCARD_PROJECTED_FIELDS: &[crate::kernel::ProjectedFieldSpec] = &[
    crate::kernel::ProjectedFieldSpec {
        field: "account_status",
        reference: "account",
        remote_field: "status",
    },
    crate::kernel::ProjectedFieldSpec {
        field: "account_customer_status",
        reference: "account",
        remote_field: "customer_status",
    },
];

impl ATMCard {
    pub fn extract_id(v: &crate::kernel::Json) -> Result<String, crate::kernel::Refusal> {
        let by_identity = (|| -> Option<String> {
            let c0 = v.dig("serial.value")?.to_id_component().ok()?;
            Some(c0)
        })();
        let by_id_key = v.get("id").and_then(|j| j.to_id_component().ok());
        let by_reference_key = v.get("atm_card").and_then(|j| j.to_id_component().ok());

        by_identity
            .or(by_id_key)
            .or(by_reference_key)
            .ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "ATMCard: no identity found (tried serial.value, id, atm_card)".to_string(),
                )
            })
    }
}

fn atmcard_invariants() -> crate::kernel::InvariantSet {
    crate::kernel::InvariantSet {
        aggregate: vec![],
        entities: vec![],
    }
}

