#[derive(Debug, Clone)]
pub struct IssueArgs {
    pub account: String,
    pub serial: CardSerial,
    pub daily_fee: DailyFee,
}

pub fn dispatch_issue(
    repo: &mut impl crate::kernel::Repository<ATMCard>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: IssueArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<ATMCard> {
    args.serial.check_invariants()?;
    args.daily_fee.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, ATMCARD_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                crate::kernel::Hydrate::Act {
                    id: __route.aggregate().to_string(),
                }
            }
            None => {
                let __hydrate_id: String = args.serial.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| ATMCard {
                        account: Some(args.account.clone()),
                        serial: Some(args.serial.clone()),
                        nickname: None,
                        daily_fee: Some(args.daily_fee.clone()),
                        withdrawals: vec![],
                        account_status: None,
                        account_customer_status: None,
                        status: "issued".to_string(),
                    }),
                    state_independent: false,
                }
            }
        },
        "Issue",
        "Banking::ATMCard",
        "ATMCard",
        "serial.value",
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "customer is active",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("account.customer.status")),
                    right: Box::new(Expr::Str("active".to_string())),
                },
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "account is open",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("account.status")),
                    right: Box::new(Expr::Str("open".to_string())),
                },
                corrects_event: None,
            },
        ],
        None,
        |record| {
            record.account = Some(args.account.clone());
            record.serial = Some(args.serial.clone());
            record.daily_fee = Some(args.daily_fee.clone());
            Ok(())
        },
        &[],
        &atmcard_invariants(),
        &["ATMCardIssued"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

