#[derive(Debug, Clone)]
pub struct WithdrawArgs {
    pub cents: WithdrawalAmount,
    pub narrative: Narrative,
}

pub fn dispatch_withdraw(
    repo: &mut impl crate::kernel::Repository<ATMCard>,
    id: &str,
    args: WithdrawArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<ATMCard> {
    args.cents.check_invariants()?;
    args.narrative.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, ATMCARD_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Withdraw",
        "Banking::ATMCard",
        "ATMCard",
        "serial.value",
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "customer is active",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("account_customer_status")),
                    right: Box::new(Expr::Str("active".to_string())),
                },
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "account is open",
                expr: Expr::Compare {
                    op: crate::kernel::Comparison {
                        less_than: false,
                        equal: true,
                        negated: false,
                    },
                    left: Box::new(Expr::Lookup("account_status")),
                    right: Box::new(Expr::Str("open".to_string())),
                },
                corrects_event: None,
            },
        ],
        Some(crate::kernel::TransitionCheck {
            field: "status",
            from_states: &["active"],
        }),
        |record| {
            record.withdrawals.push(Withdrawal {
                cents: args.cents.clone(),
                narrative: args.narrative.clone(),
                sequence: WithdrawalSequence {
                    value: record
                        .withdrawals
                        .iter()
                        .map(|e| e.sequence.value)
                        .max()
                        .unwrap_or(0)
                        + 1,
                },
                state: "taken".to_string(),
            });
            Ok(())
        },
        &[],
        &atmcard_invariants(),
        &["CashWithdrawn"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

