/// This aggregate's state, or one of its events' payloads, as a caller is answered with
/// it: each single-field value object as its bare field (the shape a command takes it in).
pub fn present(state: crate::kernel::Json) -> crate::kernel::Json {
    match state {
        crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(
            fields
                .into_iter()
                .map(|(k, v)| {
                    let new_v = match k.as_str() {
                        "account" => v,
                        "serial" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "nickname" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "daily_fee" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "amount")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "withdrawals" => match v {
                            crate::kernel::Json::Array(items) => crate::kernel::Json::Array(
                                items
                                    .into_iter()
                                    .map(|item| match item {
                                        crate::kernel::Json::Object(fields) => {
                                            crate::kernel::Json::Object(
                                                fields
                                                    .into_iter()
                                                    .map(|(k, v)| {
                                                        let new_v = match k.as_str() {
                                                            "sequence" => match v {
                                                                crate::kernel::Json::Object(
                                                                    fields,
                                                                ) => fields
                                                                    .into_iter()
                                                                    .find(|(k, _)| k == "value")
                                                                    .map_or(
                                                                        crate::kernel::Json::Null,
                                                                        |(_, field_value)| {
                                                                            field_value
                                                                        },
                                                                    ),
                                                                other => other,
                                                            },
                                                            "cents" => match v {
                                                                crate::kernel::Json::Object(
                                                                    fields,
                                                                ) => fields
                                                                    .into_iter()
                                                                    .find(|(k, _)| k == "cents")
                                                                    .map_or(
                                                                        crate::kernel::Json::Null,
                                                                        |(_, field_value)| {
                                                                            field_value
                                                                        },
                                                                    ),
                                                                other => other,
                                                            },
                                                            "narrative" => match v {
                                                                crate::kernel::Json::Object(
                                                                    fields,
                                                                ) => fields
                                                                    .into_iter()
                                                                    .find(|(k, _)| k == "text")
                                                                    .map_or(
                                                                        crate::kernel::Json::Null,
                                                                        |(_, field_value)| {
                                                                            field_value
                                                                        },
                                                                    ),
                                                                other => other,
                                                            },
                                                            _ => v,
                                                        };
                                                        (k, new_v)
                                                    })
                                                    .collect(),
                                            )
                                        }
                                        other => other,
                                    })
                                    .collect(),
                            ),
                            other => other,
                        },
                        "account_status" => v,
                        "account_customer_status" => v,
                        "cents" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "cents")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "narrative" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "text")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        _ => v,
                    };
                    (k, new_v)
                })
                .collect(),
        ),
        other => other,
    }
}
